#pragma once
inline std::string se_config_unquote(std::string value){if(value.size()>=2&&((value.front()=='"'&&value.back()=='"')||(value.front()=='\''&&value.back()=='\'')))return value.substr(1,value.size()-2);return value;}
inline SEMap<std::string> se_config_parse(const std::string& source){SEMap<std::string> out;std::istringstream stream(source);std::string line,section;while(std::getline(stream,line)){line=se_trim(line);if(line.empty()||line[0]=='#'||line[0]==';')continue;if(line.front()=='['&&line.back()==']'){section=se_trim(line.substr(1,line.size()-2));if(section.empty())throw std::runtime_error("Config section name cannot be empty.");continue;}auto eq=line.find('=');if(eq==std::string::npos)throw std::runtime_error("Expected key = value in config.");auto key=se_trim(line.substr(0,eq));if(key.empty())throw std::runtime_error("Config key cannot be empty.");out.items.emplace_back(section.empty()?key:section+"."+key,se_config_unquote(se_trim(line.substr(eq+1))));}return out;}
inline std::string se_config_get(const SEMap<std::string>& values,const std::string& key){return values.at(key);}
inline std::int64_t se_config_get_int(const SEMap<std::string>& values,const std::string& key){try{return se_int(values.at(key));}catch(const std::exception&){throw std::runtime_error("Config value is missing or is not an Int: "+key);}}
inline bool se_config_get_bool(const SEMap<std::string>& values,const std::string& key){auto value=se_lower(values.at(key));if(value=="true"||value=="yes"||value=="1")return true;if(value=="false"||value=="no"||value=="0")return false;throw std::runtime_error("Config value is not a Bool: "+key);}
inline SEMap<std::string> se_config_section(const SEMap<std::string>& values,const std::string& section){SEMap<std::string> out;auto prefix=section+".";for(const auto& pair:values.items)if(pair.first.rfind(prefix,0)==0)out.items.emplace_back(pair.first.substr(prefix.size()),pair.second);return out;}
template<class T> SEMap<T> se_config_merge(const SEMap<T>& first,const SEMap<T>& second){auto out=first.clone();for(const auto& pair:second.items)out.put(pair.first,pair.second);return out;}
inline SEMap<std::string> se_dotenv_parse(const std::string& source){SEMap<std::string> out;std::istringstream stream(source);std::string line;while(std::getline(stream,line)){line=se_trim(line);if(line.empty()||line[0]=='#')continue;if(line.rfind("export ",0)==0)line=se_trim(line.substr(7));auto eq=line.find('=');if(eq==std::string::npos)throw std::runtime_error("Expected KEY=VALUE.");auto key=se_trim(line.substr(0,eq));if(key.empty()||!(std::isalpha(static_cast<unsigned char>(key[0]))||key[0]=='_')||!std::all_of(key.begin()+1,key.end(),[](unsigned char c){return std::isalnum(c)||c=='_';}))throw std::runtime_error("Invalid configuration key.");out.items.emplace_back(key,se_config_unquote(se_trim(line.substr(eq+1))));}return out;}
inline std::string se_dotenv_get(const SEMap<std::string>& values,const std::string& key){return values.at(key);}
